using System;using System.IO;using System.Linq;using System.Text;using System.Reflection;using System.Runtime.InteropServices;using System.Collections;using System.Collections.Generic;using System.Web.Script.Serialization;
namespace PZ3D {static class GameFavoritesTests {
 [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)][DefaultDllImportSearchPaths(DllImportSearchPath.System32)]static extern int sqlite3_open_v2(byte[] f,out IntPtr db,int flags,IntPtr vfs);
 [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)][DefaultDllImportSearchPaths(DllImportSearchPath.System32)]static extern int sqlite3_exec(IntPtr db,byte[] sql,IntPtr cb,IntPtr arg,out IntPtr error);
 [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)][DefaultDllImportSearchPaths(DllImportSearchPath.System32)]static extern int sqlite3_close(IntPtr db);
 static byte[] Z(string text){return Encoding.UTF8.GetBytes(text+"\0");}static void Check(bool v,string n){if(!v)throw new Exception("FAIL: "+n);Console.WriteLine("PASS: "+n);}static JavaScriptSerializer j=new JavaScriptSerializer();static Dictionary<string,object> D(object o){return j.Deserialize<Dictionary<string,object>>(j.Serialize(o));}
 static object Call(string name,params object[] args){Type t=typeof(Program).Assembly.GetType("PZ3D.GameFavorites");Check(t!=null,"favorite service exists");try{return t.GetMethod(name).Invoke(null,args);}catch(TargetInvocationException x){throw x.InnerException;}}
 public static int Main(){try{Run();return 0;}catch(Exception x){Console.WriteLine(x);return 1;}}
 public static void Run(){string root=Path.Combine(LauncherTestPaths.Root,"favorites-"+Guid.NewGuid().ToString("N")),user=Path.Combine(root,"user"),data=Path.Combine(root,"data"),dbFile=Path.Combine(user,"db","ServerListSteam.db");Directory.CreateDirectory(Path.GetDirectoryName(dbFile));IntPtr db;Check(sqlite3_open_v2(Z(dbFile),out db,6,IntPtr.Zero)==0,"synthetic DB created");try{IntPtr error;Check(sqlite3_exec(db,Z("CREATE TABLE server(id INTEGER PRIMARY KEY,name TEXT,ip TEXT,port INTEGER,serverPassword TEXT,description TEXT); CREATE TABLE account(id INTEGER PRIMARY KEY,serverId INTEGER,username TEXT,password TEXT,isSavePassword INTEGER,isUseSteamRelay INTEGER,authType INTEGER); INSERT INTO server VALUES(1,'测试服','example.test',16261,'server-secret','<RGB:1,0,0>介绍'); INSERT INTO account VALUES(10,1,'alice','user-secret',1,0,1); INSERT INTO account VALUES(11,1,'bob','not-saved',0,1,1);"),IntPtr.Zero,IntPtr.Zero,out error)==0,"synthetic original game schema populated");}finally{sqlite3_close(db);}byte[] before=File.ReadAllBytes(dbFile);var e=new Engine(Path.Combine(root,"game"),user,data,true);var list=D(Call("List",e));var favorites=((IEnumerable)list["favorites"]).Cast<Dictionary<string,object>>().ToArray();Check(favorites.Length==2&&!j.Serialize(list).Contains("user-secret")&&!j.Serialize(list).Contains("server-secret")&&!j.Serialize(list).Contains("not-saved"),"favorite list keeps separate roles and never returns passwords");Check(!Directory.Exists(data)&&before.SequenceEqual(File.ReadAllBytes(dbFile)),"favorite reads leave game DB and launcher store untouched");Call("Import",e,new ServerProfiles(data),Convert.ToString(favorites[0]["id"]),true);string saved=File.ReadAllText(Path.Combine(data,"server-profiles.json"));Check(!saved.Contains("user-secret")&&!saved.Contains("server-secret"),"favorite import encrypts passwords in owned profile store");var profiles=D(new ServerProfiles(data).List());var rows=((IEnumerable)profiles["servers"]).Cast<Dictionary<string,object>>().ToArray();var target=new ServerProfiles(data).Target(Convert.ToString(rows[0]["id"]));Check(target.Username=="alice"&&target.UserPassword=="user-secret"&&target.ServerPassword=="server-secret","import retains exact role credentials inside native boundary");Check(before.SequenceEqual(File.ReadAllBytes(dbFile)),"import never edits original game DB");bool denied=false;try{Call("Import",e,new ServerProfiles(data),Convert.ToString(favorites[1]["id"]),false);}catch{denied=true;}Check(denied,"import requires explicit confirmation");File.WriteAllText(dbFile+"-journal","busy");var busy=D(Call("List",e));Check(((IEnumerable)busy["favorites"]).Cast<object>().Count()==0,"active journal DB is not silently treated immutable");Console.WriteLine("FAVORITES PASSED");}
}}
